{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}, {"converted": False}]) == 1 / 3
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_and_ignores_empty_groups():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


def test_conversions_in_window():
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 10) == 6
    assert conversions_in_window([], 2) == 0


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["  # header,foo,bar", "", "   ", " x , 3 , 1 ", " y, -2, 0", "z, 0, "]
    assert parse_session_log(lines) == [
        session("x", 3, True), session("y", -2, False), session("z", 0, None)
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,nope,1"])
def test_parse_errors_count_skipped_lines(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "", "  ", line])


def test_parse_rejects_invalid_flag():
    with pytest.raises(ValueError, match=r"line 1\b"):
        parse_session_log(["x,1,true"])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    first = session("a", 1, True)
    last = session("a", 3, None)
    b = session("b", 3, True)
    c = session("c", 2, False)
    assert dedupe_sessions([first, b, c, last]) == [c, last, b]
    assert dedupe_sessions([]) == []


def test_daily_counts_fill_range_and_ignore_outside():
    events = [session("a", 1, True), session("b", 3, True), session("c", 3, True),
              session("d", 2, None), session("e", 4, False), session("f", 5, True)]
    assert daily_conversion_counts(events, 2, 4) == [0, 2, 0]
    assert daily_conversion_counts(events, 4, 2) == []
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 4, True), session("c", 4, False)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary(groups, 10)["recent"] == 2
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_orders_ties_by_name():
    groups = {"z": [{"converted": True}], "empty": [], "b": [{"converted": False}],
              "a": [{"converted": True}]}
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_group_rates_include_empty_in_sorted_order():
    groups = {"z": [], "b": [{"converted": None}], "a": [{"converted": True}]}
    rates = conversion_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_zero_and_negative_values():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 1, 1, 1]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
